(function () {
  /* FAQ */
  document.querySelectorAll('.faq-q').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var open = btn.getAttribute('aria-expanded') === 'true';
      document.querySelectorAll('.faq-q').forEach(function (b) {
        b.setAttribute('aria-expanded', 'false');
        document.getElementById(b.getAttribute('aria-controls')).hidden = true;
      });
      if (!open) {
        btn.setAttribute('aria-expanded', 'true');
        document.getElementById(btn.getAttribute('aria-controls')).hidden = false;
      }
    });
  });

  /* Formulaire */
  var form = document.getElementById('signup');
  var err = document.getElementById('form-error');
  var success = document.getElementById('form-success');
  function showError(msg, field) {
    err.textContent = msg; err.hidden = false;
    form.querySelectorAll('[aria-invalid]').forEach(function (el) { el.removeAttribute('aria-invalid'); });
    if (field) { field.setAttribute('aria-invalid', 'true'); field.focus(); }
  }
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var p = form.prenom, n = form.nom, m = form.email, c = form.consentement;
    if (!p.value.trim()) return showError('Merci d’indiquer votre prénom.', p);
    if (!n.value.trim()) return showError('Merci d’indiquer votre nom.', n);
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(m.value.trim())) return showError('Cette adresse e-mail semble incomplète.', m);
    if (!c.checked) return showError('Merci d’accepter l’utilisation de vos données pour répondre à votre demande.', c);
    if (form.site_web.value) return; // anti-spam
    err.hidden = true;
    var btn = form.querySelector('button[type="submit"]');
    btn.disabled = true;
    function done() {
      document.getElementById('s-name').textContent = p.value.trim();
      document.getElementById('s-email').textContent = m.value.trim();
      form.hidden = true; success.hidden = false; success.focus();
      btn.disabled = false;
    }
    var action = form.getAttribute('action');
    if (!action || action.indexOf('[') === 0) { done(); return; } // pas encore branché : démonstration
    fetch(action, { method: 'POST', body: new FormData(form), headers: { Accept: 'application/json' } })
      .then(function (r) { if (!r.ok) throw new Error(); done(); })
      .catch(function () {
        btn.disabled = false;
        showError('L’envoi n’a pas abouti. Réessayez ou écrivez à boyer-sculpture@sfr.fr.');
      });
  });

  /* Apparition au défilement */
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); } });
    }, { threshold: 0.08 });
    document.querySelectorAll('.reveal').forEach(function (el) { io.observe(el); });
  } else {
    document.querySelectorAll('.reveal').forEach(function (el) { el.classList.add('in'); });
  }
})();
